// The live motion lab's browser reducer on states generated by the Python test, which holds
// each answer against its Python reference, `snap.py`. Prints one result per case, as JSON.
//
// Reads `{ model, cases }` as JSON on stdin: the model's source exactly as the page inlines
// it, and the generated cases.
import { readFileSync } from "node:fs";
import { runInThisContext } from "node:vm";

/**
 * @typedef {{ square_id: number, x: number, y: number }} Square
 * @typedef {{ state: object, moving: number, threshold: number }} Case
 */

/** @type {{ model: string, cases: Case[] }} */
const { model, cases } = JSON.parse(readFileSync(0, "utf8"));
runInThisContext(model, { filename: "free-quench-model.js" });
/**
 * @type {{ applyBestSnap(state: object, moving: number, threshold: number): {
 *   state: { groups: number[][], squares: Square[] },
 *   result: { target_kind: string, target_id: number } | null } }}
 */
const editor = Reflect.get(globalThis, "MotionLabEditor");
process.stdout.write(
  JSON.stringify(
    cases.map((entry) => {
      const got = editor.applyBestSnap(entry.state, entry.moving, entry.threshold);
      return {
        groups: got.state.groups,
        x: got.state.squares.map((square) => square.x),
        y: got.state.squares.map((square) => square.y),
        target: got.result ? [got.result.target_kind, got.result.target_id] : null,
      };
    }),
  ),
);
